7	/**
8	 * A simple predator-prey simulator of a safari, based on a rectangular field
9	 * containing lions, cheetahs, jaguars, zebras, gazelles, hunters and grass.
10	 *
11	 * @version 2022.03.01
12	 */
13	public class Simulator
14	{
15	    // Constants representing configuration information for the simulation.
16	    // The default width for the grid.
17	    private static final int DEFAULT_WIDTH = 175;
18	    // The default depth of the grid.
19	    private static final int DEFAULT_DEPTH = 150;
20	
21	    // The probability that each actor will be created in any given grid position.
22	    private static final double JAGUAR_CREATION_PROBABILITY = 0.011; 
23	    private static final double GAZELLE_CREATION_PROBABILITY = 0.2;
24	    private static final double LION_CREATION_PROBABILITY = 0.017 ; 
25	    private static final double PLANT_CREATION_PROBABILITY = 0.55; 
26	    private static final double CHEETAH_CREATION_PROBABILITY =0.032;
27	    private static final double ZEBRA_CREATION_PROBABILITY = 0.4998; 
28	    private static final double HUNTER_CREATION_PROBABILITY = 0.01;
29	    // How often (in steps) a random infection is introduced automatically.
30	    private static final int INFECTION_INTERVAL = 500;
31	
32	    // List of animals and plants which can not be stood on in the field.
33	    private List<Actor> animals;
34	    // List of plants that can be stood on in the field.
35	    private List<Actor> plants;
36	    // The current state of the field.
37	    private Field field;
38	    // The current step of the simulation.
39	    private int step;
40	    // A graphical view of the simulation.
41	    private SimulatorView view;
42	
43	    private boolean isDay;
44	    private Weather weather;
45	    private int numberOfDays;
46	    private static final Random rand = Randomizer.getRandom();
47	    private int noOfGrass; // keeps count of the no.of grass species in the field.
48	    /**
49	     * Construct a simulation field with default size.
50	     */
51	    public Simulator()
52	    {
53	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
54	    }
55	
56	    /**
57	     * Create a simulation field with the given size.
58	     * @param depth Depth of the field. Must be greater than zero.
59	     * @param width Width of the field. Must be greater than zero.
60	     */
61	    public Simulator(int depth, int width)
62	    {
63	        if(width <= 0 || depth <= 0) {
64	            System.out.println("The dimensions must be greater than zero.");
65	            System.out.println("Using default values.");
66	            depth = DEFAULT_DEPTH;
67	            width = DEFAULT_WIDTH;
68	        }
69	
70	        animals = new ArrayList<>();
71	        plants = new ArrayList<>();
72	        field = new Field(depth, width);
73	
74	        // Create a view of the state of each location in the field.
75	        view = new SimulatorView(depth, width, this);
76	        view.setColor(Gazelle.class, Color.ORANGE);
77	        view.setColor(Jaguar.class, Color.BLUE);
78	        view.setColor(Cheetah.class, Color.RED);
79	        view.setColor(Lion.class, Color.PINK);
80	        view.setColor(Grass.class, Color.GREEN);
81	        view.setColor(Zebra.class, Color.BLACK);
82	        view.setColor(Hunter.class, Color.MAGENTA);
83	        // Setup a valid starting point.
84	        reset();
85	    }
86	
87	    /**
88	     * Run the simulation from its current state for a reasonably long period,
89	     * (4000 steps).
90	     */
91	    public void runLongSimulation()
92	    {
93	        simulate(4000);
94	    }
95	
96	    /**
97	     * Run the simulation from its current state for the given number of steps.
98	     * Stop before the given number of steps if it ceases to be viable.
99	     * @param numSteps The number of steps to run for.
100	     */
101	    public void simulate(int numSteps)
102	    {
103	        for(int i = 1; i <= numSteps && view.isViable(field); i++) {
104	            simulateOneStep();
105	        }
106	    }
107	
108	    /**
109	     * Run the simulation from its current state for a single step.
110	     * Iterate over the whole field updating the state of each
111	     * actor in the field. One  day lasts 4 steps, with day and night alternating every 2 steps.
112	     * Buttons are disabled before the simulation starts and enabled after the simulation is finsihed.
113	     */
114	    public void simulateOneStep()
115	    {
116	        view.disableButton();
117	        step++;
118	        if(step % 2 == 0){
119	            isDay  = !isDay;
120	            if(isDay){
121	                numberOfDays++;
122	            }
123	        }
124	
125	        // Provide space for newborn actors.
126	        List<Actor> newAnimals = new ArrayList<>();  
127	        List<Actor> newGrass = new ArrayList<>();  
128	
129	        updateWeather();
130	        while(!isDay && weather == Weather.SUNNY){
131	            updateWeather();
132	        }
133	        for(Iterator<Actor> it = animals.iterator(); it.hasNext(); ) {
134	            Actor animal = it.next();
135	            animal.act(newAnimals, this);
136	            if(!animal.isActive()) {
137	                it.remove();
138	            }
139	        }
140	        animals.addAll(newAnimals);
141	        noOfGrass = 0;
142	        for(Iterator<Actor> it = plants.iterator(); it.hasNext(); ) {
143	            Actor plant = it.next();
144	            plant.act(newGrass, this);
145	            if(!plant.isActive()) {
146	                it.remove();
147	            } else {
148	                noOfGrass++;
149	            }
150	        }
151	        plants.addAll(newGrass);
152	
153	        if(step % INFECTION_INTERVAL == 0) {
154	            introduceInfection();
155	        }
156	
157	        view.showStatus(field);
158	        view.enableButton();
159	    }
160	
161	    /**
162	     * Reset the simulation to a starting position.
163	     */
164	    public void reset()
165	    {
166	        step = 0;
167	        animals.clear();
168	        plants.clear();
169	        populate();
170	        isDay = true;
171	        numberOfDays = 0;
172	        updateWeather();
173	        // Show the starting state in the view.
174	        view.showStatus(field);
175	    }
176	
177	    /**
178	     * Randomly populate the field with all the actors.
179	     */
180	    private void populate()
181	    {
182	        field.clear();
183	        for(int row = 0; row < field.getDepth(); row++) {
184	            for(int col = 0; col < field.getWidth(); col++) {
185	                Location location = new Location(row, col);
186	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
187	                    animals.add(new Lion(true, field, location));
188	                }
189	                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY) {
190	                    animals.add(new Cheetah(true, field, location));
191	                }
192	                else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
193	                    animals.add(new Gazelle(true, field, location));
194	                }
195	                else if(rand.nextDouble() <= JAGUAR_CREATION_PROBABILITY) {
196	                    animals.add(new Jaguar(true, field, location));
197	                }
198	                else if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
199	                    plants.add(new Grass(true, field, location));
200	                }
201	                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
