5	/**
6	 * An actor is a representation of a living thing in the simulation.
7	 *
8	 * @version 2022.03.01
9	 */
10	public abstract class Actor 
11	{
12	    // The actor's field.
13	    private Field field;
14	    // The actor's position in the field.
15	    private Location location;
16	    // Whether the actor is alive or not.
17	    private boolean alive;
18	    //The actor's age
19	    private int age;
20	    //how much the actor grows. This is added to the animals food level.
21	    private double growthLevel;
22	    // A shared random number generator to control breeding.
23	    private static final Random rand = Randomizer.getRandom();
24	    /**
25	     * Create a new actor at location in field.
26	     * 
27	     * @param field The field currently occupied.
28	     * @param location The location within the field.
29	     */
30	    public Actor(Field field, Location location)
31	    {
32	        this.field = field;
33	        setLocation(location);
34	        alive = true;
35	    }
